// Package api: router.go registers the OpenAPI-derived routes onto a Fiber app.
//
// All public routes are defined in api/openapi.yaml and code-generated by
// oapi-codegen into apigen.RegisterHandlers. This file is the single wiring
// point: program/ calls api.RegisterRoutes(app) after the middleware stack is
// in place. Per-area route groups (compute, dns, ...) will be added here as
// their WSs land; for WS-05 only the generated routes exist.
package api

import (
	"github.com/avestura/lahijan/api/gen/go"
	"github.com/gofiber/fiber/v2"
)

// RegisterRoutes wires the OpenAPI-derived server onto app. The handlers live
// in server.go; the routing table is generated by oapi-codegen (apigen) so it
// cannot drift from the spec. Per-area groups get appended below as they land.
func RegisterRoutes(app *fiber.App) {
	server := NewServer()
	apigen.RegisterHandlers(app, server)
}
